select vote_id, title, description, vote_type, start_time, end_time, status, creator_user_id, creator_nick_name, create_time from bbs_vote
and status = #{status}
order by create_time desc

select form_id, title, description, form_schema, status, creator_user_id, creator_nick_name, create_time from bbs_demand_form
and status = #{status}
order by create_time desc

select activity_id, title, content, start_time, end_time, status, join_count, creator_user_id, creator_nick_name, create_time from bbs_topic_activity
and status = #{status}
order by create_time desc
